package com.ukulele.monitor;
import java.util.*;
/** Editable source timing/fingering, independent of device-event quantization. */
final class ScoreDraft {
 static final class Parsed {final ArrayList<ScorePitch.Note> notes=new ArrayList<>();long durationMs=-1;}
 static String text(List<ScorePitch.Note> notes,long durationMs){StringBuilder b=new StringBuilder("# 时间毫秒,音名,弦:品位（最后一项可省略）\n# duration_ms="+durationMs+"\n");for(ScorePitch.Note n:notes){b.append(n.time).append(',').append((n.midi<0?"REST":ScorePitch.name(n.midi)));if(n.preferredColumn>=0)b.append(',').append("GCEA".charAt(n.preferredColumn)).append(':').append(n.midi-ScorePitch.OPEN[n.preferredColumn]);b.append('\n');}return b.toString();}
 static int pitch(String text){java.util.regex.Matcher m=java.util.regex.Pattern.compile("^([A-Ga-g])([#b]?)(-?\\d+)$").matcher(text.trim());if(!m.matches())return -1;int pc=new int[]{9,11,0,2,4,5,7}[Character.toUpperCase(m.group(1).charAt(0))-'A'];int n=(Integer.parseInt(m.group(3))+1)*12+pc+(m.group(2).equals("#")?1:m.group(2).equals("b")?-1:0);return n>=0&&n<=127?n:-1;}
 static Parsed parse(String text){Parsed p=new Parsed();int lineNo=0;for(String line:text.split("\\r?\\n")){lineNo++;line=line.trim();if(line.startsWith("# duration_ms=")){p.durationMs=Long.parseLong(line.substring(14).trim());if(p.durationMs<0||p.durationMs>7200000)throw new IllegalArgumentException("时长超出范围");continue;}if(line.startsWith("# unresolved=")){if(Integer.parseInt(line.substring(13).trim())>0)throw new IllegalArgumentException("请先在简谱校对中补齐 ? 音符");continue;}if(line.isEmpty()||line.startsWith("#"))continue;String[] fields=line.split("[,，\\s]+");if(fields.length<2||fields.length>3)throw new IllegalArgumentException("第"+lineNo+"行应为：时间毫秒,音名[,弦:品位]");boolean rest=fields[1].equalsIgnoreCase("REST")||fields[1].equals("休止");int midi=rest?-1:pitch(fields[1]);long t=Long.parseLong(fields[0]);if((midi<0&&!rest)||t<0||t>7200000)throw new IllegalArgumentException("第"+lineNo+"行音名/时间无效");int c=-1;if(fields.length==3){if(rest)throw new IllegalArgumentException("休止事件不能指定品位");String[] fret=fields[2].toUpperCase(java.util.Locale.ROOT).split(":");if(fret.length!=2||fret[0].length()!=1||(c="GCEA".indexOf(fret[0]))<0)throw new IllegalArgumentException("弦号应为G/C/E/A");int f=Integer.parseInt(fret[1]);if(f<0||f>24||ScorePitch.OPEN[c]+f!=midi)throw new IllegalArgumentException("第"+lineNo+"行指法与音高不一致");}p.notes.add(new ScorePitch.Note(t,midi,c));if(p.notes.size()>10922)throw new IllegalArgumentException("曲谱超过设备容量");}if(p.notes.isEmpty())throw new IllegalArgumentException("请输入音符");return p;}
}
